const { Document, Packer, Paragraph, TextRun } = require("docx");
const fs = require("fs");
const path = require("path");

const filePath = path.join(__dirname, "docs", "travel_summary.docx");

async function createDoc() {
  const lines = [
    { label: "Reservation Code", value: "B75309" },
    { label: "Flight", value: "FL398507" },
    { label: "From", value: "LAX" },
    { label: "To", value: "LAS" },
    { label: "Date", value: "2026-09-16" },
    { label: "Class", value: "Economy" },
    { label: "Payment", value: "$129 (Visa cc_9cdfc95d)" },
  ];

  const paragraphs = lines.map(
    ({ label, value }) =>
      new Paragraph({
        children: [
          new TextRun({ text: `${label}: `, bold: true }),
          new TextRun({ text: value }),
        ],
      })
  );

  const doc = new Document({
    sections: [{ children: paragraphs }],
  });

  const buffer = await Packer.toBuffer(doc);
  fs.writeFileSync(filePath, buffer);
  console.log("Created", filePath);
}

createDoc().catch(console.error);
